// scripts/embed-bridge.js — embed the Unity bridge source (v0.5.0, v0.6.1).
//
// Reads unity-companion/CodeFoxBridge.cs and writes
// unity-bridge-source.js, a GENERATED file (gitignored, like the icons)
// that exports the bridge source as a string. The app installs the
// bridge from the bundled file when the install has it, and from this
// embedded copy when it does not — so a missing bundled file can never
// break the install again. Runs before every build (see package.json),
// on `npm install` (postinstall) and on `npm start` (prestart), so a
// fresh clone always has the file without it being tracked in git.
//
// Run: node scripts/embed-bridge.js

const fs = require('fs');
const path = require('path');

const src = path.join(__dirname, '..', 'unity-companion', 'CodeFoxBridge.cs');
const dst = path.join(__dirname, '..', 'unity-bridge-source.js');

const source = fs.readFileSync(src, 'utf8');
if (!source || source.length < 100) {
  throw new Error('unity-companion/CodeFoxBridge.cs is missing or empty — cannot embed the bridge source.');
}

const out = '// Generated by scripts/embed-bridge.js from unity-companion/CodeFoxBridge.cs.\n'
  + '// Do not edit by hand — re-run `node scripts/embed-bridge.js` (it also runs\n'
  + '// before every build). This is the fallback the app installs the bridge from\n'
  + '// when the bundled companion file is not in the installed app.\n'
  + 'module.exports = { BRIDGE_SOURCE: ' + JSON.stringify(source) + ' };\n';

fs.writeFileSync(dst, out, 'utf8');
console.log('Wrote ' + path.relative(path.join(__dirname, '..'), dst)
  + ' (' + source.length + ' chars of bridge source)');
